// DsLogoArt — the title card's logo.
//
// Ours, not the game's: docs/Bottom_Screen_Logo.webp, embedded as PNG base64
// for the same reason as DsTrashArt. The conversion whitens the fully
// transparent pixels, which the WebP stores as black and bilinear filtering
// would otherwise blend into a dark fringe.

#if UNITY_ANDROID && !UNITY_EDITOR
using System;
using UnityEngine;

public static class DsLogoArt
{
    const string Png = "";

    static Sprite _sprite;
    static bool _tried;

    /// <summary>Null if the art will not decode, which leaves the card blank.</summary>
    public static Sprite Sprite
    {
        get
        {
            if (_tried) return _sprite;
            _tried = true;
            try
            {
                var tex = new Texture2D(2, 2, TextureFormat.RGBA32, false) { name = "DsLogo" };
                if (!tex.LoadImage(Convert.FromBase64String(Png), true))
                {
                    UnityEngine.Object.Destroy(tex);
                    Debug.LogWarning("[DsLogoArt] PNG did not decode");
                    return null;
                }
                tex.wrapMode = TextureWrapMode.Clamp;
                tex.filterMode = FilterMode.Bilinear;
                tex.hideFlags = HideFlags.HideAndDontSave;
                _sprite = Sprite.Create(tex, new Rect(0f, 0f, tex.width, tex.height),
                                        new Vector2(0.5f, 0.5f), 100f, 0, SpriteMeshType.FullRect);
                _sprite.name = "DsLogo";
                _sprite.hideFlags = HideFlags.HideAndDontSave;
            }
            catch (Exception e)
            {
                Debug.LogWarning("[DsLogoArt] failed: " + e.Message);
            }
            return _sprite;
        }
    }
}
#endif
